/**
 * Unit tests for DOMNodePointer.findEnclosingAttribute.
 * Since the method is protected, this test class is placed in the same package.
 */
public class DOMNodePointer_findEnclosingAttribute_TriageGen1Test {

    private Document createDocument() throws Exception {
        DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
        DocumentBuilder builder = factory.newDocumentBuilder();
        return builder.newDocument();
    }

    @Test
    public void testFindEnclosingAttribute_NullNode() throws Exception {
        Document doc = createDocument();
        // Testing n = null
        String result = DOMNodePointer.findEnclosingAttribute(null, "testAttr");
        assertNull(result);
    }

    @Test
    public void testFindEnclosingAttribute_AttributeFoundOnCurrentNode() throws Exception {
        Document doc = createDocument();
        Element root = doc.createElement("root");
        root.setAttribute("target", "value1");
        doc.appendChild(root);

        String result = DOMNodePointer.findEnclosingAttribute(root, "target");
        assertEquals("value1", result);
    }

    @Test
    public void testFindEnclosingAttribute_AttributeFoundOnParent() throws Exception {
        Document doc = createDocument();
        Element root = doc.createElement("root");
        root.setAttribute("target", "value1");
        Element child = doc.createElement("child");
        root.appendChild(child);
        doc.appendChild(root);

        String result = DOMNodePointer.findEnclosingAttribute(child, "target");
        assertEquals("value1", result);
    }

    @Test
    public void testFindEnclosingAttribute_AttributeFoundOnGrandparent() throws Exception {
        Document doc = createDocument();
        Element root = doc.createElement("root");
        root.setAttribute("target", "value1");
        Element child = doc.createElement("child");
        Element grandchild = doc.createElement("grandchild");

        root.appendChild(child);
        child.appendChild(grandchild);
        doc.appendChild(root);

        String result = DOMNodePointer.findEnclosingAttribute(grandchild, "target");
        assertEquals("value1", result);
    }

    @Test
    public void testFindEnclosingAttribute_AttributeIsEmptyOrNullOnIntermediateNodes() throws Exception {
        Document doc = createDocument();
        Element root = doc.createElement("root");
        root.setAttribute("target", "value1");

        Element child = doc.createElement("child");
        child.setAttribute("target", ""); // Empty string case

        Element grandchild = doc.createElement("grandchild");
        // grandchild has no target attribute (returns empty string in some DOM impls, or null)

        root.appendChild(child);
        child.appendChild(grandchild);
        doc.appendChild(root);

        // Should skip child (empty) and grandchild (none) and find root
        String result = DOMNodePointer.findEnclosingAttribute(grandchild, "target");
        assertEquals("value1", result);
    }

    @Test
    public void testFindEnclosingAttribute_AttributeNotFoundAnywhere() throws Exception {
        Document doc = createDocument();
        Element root = doc.createElement("root");
        Element child = doc.createElement("child");
        root.appendChild(child);
        doc.appendChild(root);

        String result = DOMNodePointer.findEnclosingAttribute(child, "nonExistent");
        assertNull(result);
    }

    @Test
    public void testFindEnclosingAttribute_NonElementNode() throws Exception {
        Document doc = createDocument();
        Element root = doc.createElement("root");
        root.setAttribute("target", "value1");

        // Create a Text Node
        Node textNode = doc.createTextNode("hello");
        root.appendChild(textNode);

        // Text node is not an ELEMENT_NODE, should skip to parent (root)
        String result = DOMNodePointer.findEnclosingAttribute(textNode, "target");
        assertEquals("value1", result);
    }

    @Test
    public void testFindEnclosingAttribute_AttributeIsLiteralNull() throws Exception {
        // This simulates the case where getAttribute returns null if not present
        // (Behavior varies by DOM implementation, but we cover the branch)
        Document doc = createDocument();
        Element root = doc.createElement("root");
        // Note: In standard DOM, getAttribute returns empty string if not found, 
        // but the code handles both null and empty.
        doc.appendChild(root);

        String result = DOMNodePointer.findEnclosingAttribute(root, "missing");
        assertNull(result);
    }
}
